```javascript
interface Format {
  serialize(obj: any): string;
  deserialize(text: string): any;
}
class Registry {
  private formats = new Map<string, Format>();
  register(name: string, fmt: Format) { this.formats.set(name, fmt); }
  get(name: string): Format { return this.formats.get(name)!; }
}
```

